import os, re, subprocess, sys, tempfile

FILTER = "/app/filter.py"

# normalise an attribute value the same way a browser sees it before URI parsing
def norm(v):
    v = v or ""
    if isinstance(v, (list, tuple)): v = " ".join(map(str, v))
    import html
    v = html.unescape(str(v))
    v = re.sub(r'[\x00-\x20\x7f]+', '', v)
    return v

SCHEME = re.compile(r'^(?:javascript|vbscript):', re.I)

def dangerous_in(s):
    """Return list of problems found in a filtered HTML string."""
    import bs4
    problems = []
    soup = bs4.BeautifulSoup(s, "html.parser")
    for t in soup.find_all("script"):
        problems.append("<script> remains")
    for t in soup.find_all(True):
        for a, v in t.attrs.items():
            if a.lower().startswith("on"):
                problems.append(f"on* handler remains: {a}")
            if SCHEME.match(norm(v)):
                problems.append(f"scheme URI remains: {a}={v!r}")
            if a.lower() == "style":
                sv = norm(v)
                if re.search(r'url\(\s*[\'"]?\s*(javascript|vbscript)\s*:', sv, re.I):
                    problems.append(f"style url(js) remains: {v!r}")
            if a.lower() == "srcdoc" and "<script" in norm(v).lower():
                problems.append("srcdoc <script> remains")
            if t.name == "meta" and (t.attrs.get("http-equiv","") or "").lower()=="refresh":
                m = re.search(r'url=(.*)$', norm(v), re.I)
                if m and SCHEME.match(m.group(1)):
                    problems.append(f"meta refresh js remains: {v!r}")
    return problems

CASES = [
 ("basic script", '<!DOCTYPE html><html><head><script>bad()</script></head><body><h1>Hi</h1><p class="a">text</p></body></html>'),
 ("ext script", '<html><body><script src="evil.js"></script><p>keep</p></body></html>'),
 ("href js", '<html><body><a href="javascript:alert(1)">x</a><a href="https://ok.com">y</a></body></html>'),
 ("mixedcase js", '<html><body><a href="JaVaScRiPt:alert(1)">x</a></body></html>'),
 ("entity tab js", '<html><body><a href="jav&#x09;ascript:alert(1)">x</a></body></html>'),
 ("entity n js", '<html><body><a href="&#106;avascript:alert(1)">x</a></body></html>'),
 ("entity colon js", '<html><body><a href="javascript&#58;alert(1)">x</a></body></html>'),
 ("vbscript", '<html><body><a href="vbscript:msgbox(1)">x</a></body></html>'),
 ("lead whitespace", '<html><body><a href="  javascript:alert(1)">x</a></body></html>'),
 ("lead newline", '<html><body><a href="\njavascript:alert(1)">x</a></body></html>'),
 ("lead tab", '<html><body><a href="\tjavascript:alert(1)">x</a></body></html>'),
 ("on handlers", '<html><body><img src="x" onerror="a()"><div onclick="b()" onmouseover="c()" d="1">x</div></body></html>'),
 ("svg onload", '<html><body><svg onload="a()"><circle r="1"/></svg></body></html>'),
 ("form action js", '<html><body><form action="javascript:submit()"><input name="q"></form></body></html>'),
 ("button formaction", '<html><body><button formaction="javascript:a()">b</button></body></html>'),
 ("object data", '<html><body><object data="javascript:a()"></object></body></html>'),
 ("embed src", '<html><body><embed src="javascript:a()"></body></html>'),
 ("meta refresh js", '<html><head><meta http-equiv="refresh" content="0;url=javascript:alert(1)"></head><body>x</body></html>'),
 ("meta refresh ok", '<html><head><meta http-equiv="refresh" content="0;url=/next.html"></head><body>x</body></html>'),
 ("style url js", '<html><body><div style="background:url(javascript:alert(1))">x</div></body></html>'),
 ("style url quoted js", '<html><body><div style="background:url(\'javascript:alert(1)\')">x</div></body></html>'),
 ("style url ok", '<html><body><div style="color:red; background:url(https://ok.com/i.png)">x</div></body></html>'),
 ("srcdoc js", '<html><body><iframe srcdoc="<b>hi</b><script>a()</script>"></iframe></body></html>'),
 ("xlink js", '<html><body><svg><a xlink:href="javascript:a()"><text>x</text></a></svg></body></html>'),
 ("legit links kept", '<html><body><a href="https://example.com/js-tutorial.html">a</a><a href="/js/javascript:weird.html">b</a><img src="c.png" alt="c"><p>keep</p></body></html>'),
 ("table kept", '<html><body><table><tr><th>A</th></tr><tr><td>1</td></tr></table></body></html>'),
 ("headers kept", '<html><body><h1>One</h1><h2>Two</h2><p class="c" id="i" data-x="y">t</p></body></html>'),
 ("no trailing nl", '<html><body><script>a()</script><p>x</p></body></html>'),
 ("trailing nl", '<html><body><script>a()</script><p>x</p></body></html>\n'),
]

ok = True
for name, content in CASES:
    d = tempfile.mkdtemp()
    p = os.path.join(d, "f.html")
    with open(p, "w", encoding="utf-8") as f: f.write(content)
    r = subprocess.run([sys.executable, FILTER, p], capture_output=True, text=True)
    if r.returncode != 0:
        print(f"FAIL [{name}] exit {r.returncode}: {r.stderr.strip()}"); ok=False; continue
    with open(p, encoding="utf-8") as f: out = f.read()
    probs = dangerous_in(out)
    # preservation checks for specific cases
    if "legit links kept" == name:
        for s in ['https://example.com/js-tutorial.html', '/js/javascript:weird.html', 'c.png', 'alt="c"', 'keep']:
            if s not in out: probs.append(f"lost legit content: {s}")
    if "table kept" == name:
        for s in ['<table', '<th>A</th>', '<td>1</td>', '</table>']:
            if s not in out: probs.append(f"lost table: {s}")
    if "headers kept" == name:
        for s in ['<h1>One</h1>', '<h2>Two</h2>', 'class="c"', 'id="i"', 'data-x="y"']:
            if s not in out: probs.append(f"lost header/attr: {s}")
    if "meta refresh ok" == name:
        if 'url=/next.html' not in out: probs.append("lost legit meta refresh")
    if "style url ok" == name:
        if 'url(https://ok.com/i.png)' not in out: probs.append("lost legit style url")
    if "no trailing nl" == name and out.endswith("\n"):
        probs.append("added trailing newline that was not there")
    if "trailing nl" == name and not out.endswith("\n"):
        probs.append("dropped trailing newline that was there")
    if probs:
        print(f"FAIL [{name}]:");
        for x in probs: print("    -", x)
        ok = False
    else:
        print(f"PASS [{name}]")

# idempotency on the basic case
d = tempfile.mkdtemp(); p=os.path.join(d,"f.html")
with open(p,"w") as f: f.write(CASES[0][1])
subprocess.run([sys.executable, FILTER, p])
first = open(p).read()
subprocess.run([sys.executable, FILTER, p])
second = open(p).read()
if first==second: print("PASS [idempotency]")
else: print("FAIL [idempotency] differs on second run"); ok=False

print("\nALL PASS" if ok else "\nSOME FAILED")
sys.exit(0 if ok else 1)
